CREATE TABLE projected_work_institution WITH (format='PARQUET',write_compression='ZSTD') AS SELECT DISTINCT try_cast(regexp_extract(w.id, '[A-Z]([0-9]+)$', 1) AS bigint) AS work_id,try_cast(regexp_extract(a.author.id, '[A-Z]([0-9]+)$', 1) AS bigint) AS author_id,try_cast(regexp_extract(i.id, '[A-Z]([0-9]+)$', 1) AS bigint) AS institution_id FROM raw_works w CROSS JOIN UNNEST(w.authorships) AS u(a) CROSS JOIN UNNEST(a.institutions) AS v(i) WHERE try_cast(regexp_extract(w.id, '[A-Z]([0-9]+)$', 1) AS bigint) IS NOT NULL AND try_cast(regexp_extract(a.author.id, '[A-Z]([0-9]+)$', 1) AS bigint) IS NOT NULL AND try_cast(regexp_extract(i.id, '[A-Z]([0-9]+)$', 1) AS bigint) IS NOT NULL;
